 1	import java.util.ArrayList;
 2	import java.util.Arrays;
 3	import java.util.List;
 4	import java.util.Objects;
 5	
 6	public final class BucketSort {
 7	
 8	    private static final float MIN_SUPPORTED_VALUE = 0.0f;
 9	    private static final float MAX_SUPPORTED_VALUE = 1.0f;
10	
11	    private BucketSort() {
12	    }
13	
14	    public static void sort(float[] values) {
15	        Objects.requireNonNull(values, "values");
16	        sortInPlace(values);
17	    }
18	
19	    public static float[] sortedCopy(float[] values) {
20	        Objects.requireNonNull(values, "values");
21	
22	        float[] copy = Arrays.copyOf(values, values.length);
23	        sortInPlace(copy);
24	        return copy;
25	    }
26	
27	    private static void sortInPlace(float[] values) {
28	        if (values.length == 0) {
29	            return;
30	        }
31	
32	        List<List<Float>> buckets = createBuckets(values.length);
33	        distributeValues(values, buckets);
34	        sortBuckets(buckets);
35	        mergeBuckets(buckets, values);
36	    }
37	
38	    private static List<List<Float>> createBuckets(int bucketCount) {
39	        List<List<Float>> buckets = new ArrayList<>(bucketCount);
40	        for (int i = 0; i < bucketCount; i++) {
41	            buckets.add(new ArrayList<>());
42	        }
43	        return buckets;
44	    }
45	
46	    private static void distributeValues(float[] values, List<List<Float>> buckets) {
47	        int bucketCount = buckets.size();
48	        for (float value : values) {
49	            validateValue(value);
50	            int bucketIndex = bucketIndexFor(value, bucketCount);
51	            buckets.get(bucketIndex).add(value);
52	        }
53	    }
54	
55	    private static void sortBuckets(List<List<Float>> buckets) {
56	        for (List<Float> bucket : buckets) {
57	            insertionSort(bucket);
58	        }
59	    }
60	
61	    private static void mergeBuckets(List<List<Float>> buckets, float[] values) {
62	        int index = 0;
63	        for (List<Float> bucket : buckets) {
64	            for (float value : bucket) {
65	                values[index++] = value;
66	            }
67	        }
68	    }
69	
70	    private static void insertionSort(List<Float> bucket) {
71	        for (int i = 1; i < bucket.size(); i++) {
72	            float currentValue = bucket.get(i);
73	            int j = i - 1;
74	            while (j >= 0 && bucket.get(j) > currentValue) {
75	                bucket.set(j + 1, bucket.get(j));
76	                j--;
77	            }
78	            bucket.set(j + 1, currentValue);
79	        }
80	    }
81	
82	    private static int bucketIndexFor(float value, int bucketCount) {
83	        return (int) (bucketCount * value);
84	    }
85	
86	    private static void validateValue(float value) {
87	        if (value < MIN_SUPPORTED_VALUE || value >= MAX_SUPPORTED_VALUE) {
88	            throw new IllegalArgumentException(
89	                "Bucket sort expects values in the range ["
90	                    + MIN_SUPPORTED_VALUE
91	                    + ", "
92	                    + MAX_SUPPORTED_VALUE
93	                    + "): "
94	                    + value
95	            );
96	        }
97	    }
98	}

